//   B矩阵: [C*R*S, K]      — 每个filter展开为一列
//   C矩阵: [N*P*Q, K]      — 输出

// 传统im2col方法:
float* A_col = im2col(x, N, H, W, C, R, S, P, Q);  // 显式构造，内存开销大
gemm(A_col, w_reshaped, y_reshaped, N*P*Q, K, C*R*S);

